import Link from 'next/link';
import pool from '../lib/db';

export const metadata = {
  title: 'เว็บไซต์ของฉัน',
  description: 'ระบบจัดการหน้าเว็บและ SEO อัตโนมัติ',
}

export default async function RootLayout({ children }) {
  // ดึงรายการหน้าหลักจากฐานข้อมูลมาทำลิงก์ดรอปดาว์นอัตโนมัติ
  let pages = [];
  try {
    const [rows] = await pool.query('SELECT title, slug_path FROM pages WHERE parent_id IS NULL');
    pages = rows;
  } catch (error) {
    console.error("Database connection error in layout:", error);
  }

  return (
    <html lang="th">
      <body style={{ margin: 0, display: 'flex', flexDirection: 'column', minHeight: '100vh', position: 'relative' }}>
        
        {/* แถบด้านบนสุด (Navbar) มี PALIMIAN ทางซ้าย และเมนูดรอปดาว์นทางขวา */}
        <header style={{ 
          position: 'absolute', 
          top: 0, 
          left: 0, 
          width: '100%', 
          padding: '1.2rem 2rem', 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          boxSizing: 'border-box', 
          zIndex: 1000, 
          fontFamily: 'serif' 
        }}>
          {/* ชื่อเว็บทางซ้ายสุด */}
          <Link href="/" style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#1A1A1A', textDecoration: 'none', letterSpacing: '1px' }}>
            PALIMIAN
          </Link>

          {/* ดรอปดาว์นเมนูทางขวาสุด */}
          <div className="dropdown-container" style={{ position: 'relative', display: 'inline-block', fontFamily: 'sans-serif' }}>
            <div 
              style={{ 
                backgroundColor: '#1A1A1A', 
                color: '#FFF', 
                padding: '0.5rem 1rem', 
                borderRadius: '4px', 
                fontSize: '0.9rem', 
                cursor: 'pointer',
                userSelect: 'none'
              }}
            >
              เมนูหน้าเว็บ ▼
            </div>
            
            {/* รายการดรอปดาว์น */}
            <div 
              className="dropdown-menu"
              style={{ 
                display: 'none', 
                position: 'absolute', 
                right: 0, 
                top: '100%', 
                backgroundColor: '#FFFFFF', 
                minWidth: '180px', 
                boxShadow: '0 4px 12px rgba(0,0,0,0.1)', 
                borderRadius: '4px', 
                border: '1px solid #EBE7DF',
                marginTop: '0.5rem',
                overflow: 'hidden',
                zIndex: 1001
              }}
            >
              <Link 
                href="/" 
                style={{ display: 'block', padding: '0.75rem 1rem', color: '#1A1A1A', textDecoration: 'none', fontSize: '0.9rem', borderBottom: '1px solid #f0f0f0' }}
              >
                หน้าแรก
              </Link>
              {pages.map((p) => (
                <Link 
                  key={p.slug_path} 
                  href={`/${p.slug_path}`} 
                  style={{ display: 'block', padding: '0.75rem 1rem', color: '#1A1A1A', textDecoration: 'none', fontSize: '0.9rem', borderBottom: '1px solid #f0f0f0' }}
                >
                  {p.title}
                </Link>
              ))}
            </div>
          </div>

          {/* CSS เพื่อให้เมนูดรอปดาว์นแสดงผลตอนเอาเมาส์ชี้ */}
          <style>{`
            .dropdown-container:hover .dropdown-menu {
              display: block !important;
            }
          `}</style>
        </header>

        {/* เนื้อหาหลัก (เพิ่ม padding-top เผื่อพื้นที่ให้แถบ Navbar ด้านบนไม่ทับเนื้อหา) */}
        <div style={{ flex: 1, paddingTop: '4rem' }}>
          {children}
        </div>
        
        {/* แถบช่องทางติดต่อด้านล่างทุกหน้า */}
        <footer style={{ backgroundColor: '#1A1A1A', color: '#FFF', padding: '1.5rem 2rem', fontFamily: 'sans-serif', marginTop: 'auto' }}>
          <div style={{ maxWidth: '1100px', margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem' }}>
            <div>
              <p style={{ margin: 0, fontWeight: 'bold', fontSize: '1.1rem' }}>ช่องทางติดต่อเรา</p>
              <p style={{ margin: '0.25rem 0 0 0', fontSize: '0.9rem', color: '#ccc' }}>โทร: 02-XXX-XXXX | อีเมล: palimian.varee@gmail.com</p>
            </div>
            <div style={{ display: 'flex', gap: '1rem', fontSize: '0.9rem' }}>
              <span style={{ color: '#ccc' }}>Line: @978wnmxg</span>
              <span style={{ color: '#ccc' }}>Facebook: MyWebsite</span>
            </div>
          </div>
        </footer>
      </body>
    </html>
  )
}